<div class="d-flex justify-content-between align-items-center mb-4"><h1>📥 Historial de Ingresos</h1><a href="index.php?controller=ingreso&action=registrar" class="btn btn-success">➕ Nuevo Ingreso</a></div>
<?php if(empty($ingresos)): ?><div class="alert alert-info">No hay ingresos registrados.</div><?php else: ?><div class="card"><div class="card-body table-responsive"><table class="table table-striped align-middle"><thead class="table-dark"><tr><th>Fecha</th><th>Producto</th><th>Proveedor</th><th>Cantidad</th><?php if(($_SESSION['user_role']??'')==='admin'): ?><th>Acciones</th><?php endif; ?></tr></thead><tbody>
<?php foreach($ingresos as $i): ?><tr><td><?= date('d/m/Y H:i',strtotime($i['Fecha_Ingreso'])) ?></td><td><?= htmlspecialchars($i['ProductoNombre'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($i['ProveedorNombre'],ENT_QUOTES,'UTF-8') ?></td><td><span class="badge bg-success"><?= (int)$i['Cantidad'] ?></span></td><?php if(($_SESSION['user_role']??'')==='admin'): ?><td class="text-nowrap"><button class="btn btn-sm btn-outline-primary edit-ingreso" data-bs-toggle="modal" data-bs-target="#editIngreso" data-id="<?= (int)$i['ID_Ingreso'] ?>" data-producto="<?= (int)$i['ID_Producto'] ?>" data-proveedor="<?= (int)$i['ID_Proveedor'] ?>" data-cantidad="<?= (int)$i['Cantidad'] ?>">Actualizar</button><form class="d-inline" method="post" action="index.php?controller=ingreso&action=eliminar" onsubmit="return confirm('¿Eliminar ingreso y descontar esa cantidad del stock?')"><input type="hidden" name="id" value="<?= (int)$i['ID_Ingreso'] ?>"><button class="btn btn-sm btn-outline-danger">Eliminar</button></form></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
<?php if(($_SESSION['user_role']??'')==='admin'): ?><div class="modal fade" id="editIngreso" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><form class="modal-content" method="post" action="index.php?controller=ingreso&action=actualizar"><div class="modal-header"><h5 class="modal-title">Actualizar ingreso</h5><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="ID_Ingreso" id="ingId"><div class="mb-3"><label class="form-label">Producto</label><select class="form-select" name="ID_Producto" id="ingProd" required><?php foreach($productos as $p): ?><option value="<?= (int)$p['ID_Producto'] ?>"><?= htmlspecialchars($p['Nombre'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></div><div class="mb-3"><label class="form-label">Proveedor</label><select class="form-select" name="ID_Proveedor" id="ingProv" required><?php foreach($proveedores as $p): ?><option value="<?= (int)$p['ID_Proveedor'] ?>"><?= htmlspecialchars($p['Razon_Social'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></div><div class="mb-3"><label class="form-label">Cantidad</label><input class="form-control" type="number" min="1" name="Cantidad" id="ingCant" required></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar cambios</button></div></form></div></div><script>document.querySelectorAll('.edit-ingreso').forEach(b=>b.addEventListener('click',function(){document.getElementById("ingId").value=this.dataset.id;document.getElementById("ingProd").value=this.dataset.producto;document.getElementById("ingProv").value=this.dataset.proveedor;document.getElementById("ingCant").value=this.dataset.cantidad;}));</script><?php endif; ?>
